from pathlib import Path
import base64,json
R=Path(__file__).resolve().parents[2]
O=R/'renders/temple_reseau_ledian_v1'
P=Path(__file__).resolve().parent/'references'
m=json.loads((O/'manifest.json').read_text())
def uri(p): return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={e['id']:{**e,'images':{n:uri(O/e['id']/(n+'.png')) for n in e['layers']},'schema':uri(O/e['id']/'schema.png')} for e in m['rooms']}
# reference temple
ref_uri=uri(P/'reference_temple.png')
planche_uri=uri(O/'PLANCHE.png') if (O/'PLANCHE.png').exists() else ref_uri
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Temple · réseau style Ledian</title><style>*{box-sizing:border-box}body{margin:0;background:#18141f;color:#e8e0f0;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#c8bed6;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#cbb4e8}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #8a6ab8;border-radius:6px;background:#2f2640;color:#f0e8ff}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#1b1824}aside{background:#262136;padding:18px;border-radius:8px}label{display:block;margin:15px 0;font-size:14px}a{color:#d6c0ff}small{color:#bdb0d6}footer{border-top:1px solid #4d3d68}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">TEMPLE / RÉSEAU STYLE LEDIAN / 6 SALLES</div><h1>Réseau temple — six variantes vides</h1><p>Dalles claires, murs violets ornés et bordure rocheuse brune, d’après <b>IMG_5004.png 408×408</b>. Variantes générées guidées par cette référence, découpées en calques multicouches. Texture canonique réutilisée sans recoloration sauvage, DA préservée. Aucun mobilier ni personnage ajouté.</p><p><small>Référence canonique affichée à l’échelle · 6 pièces 512×512 · 15 ports 64px · calques alignés · patch de raccord natif</small></p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma des accès</button><button id="reference">Voir référence canonique</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><p id="status"></p></section><aside><b>Calques alignés · 512 × 512</b><div id="layers"></div><small>Les raccords de sol sont indépendants et partagent la même bande 64px. Le petit fragment d’autel est disponible sur la salle latérale et désactivé par défaut. Les murs/rochers sont des partitions visibles, pas des volumes reconstruits derrière.</small></aside></div><p><img src="__PLANCHE__" style="width:100%;image-rendering:pixelated;border:1px solid #4d3d68"></p></main><footer><p>Source : IMG_5004.png (temple) — autel + colonnes + dalles. Générations guidées sur magenta, découpées et vérifiées. Patch de raccord et fragment d’autel proviennent directement des pixels sources (140,200)-(180,232) et (160,140)-(200,200).</p><small>15 ports de 64px : sol opaque et bande de jonction commune vérifiés. Cela ne valide ni les collisions, ni le raccord total de la silhouette rocheuse, ni les transitions PMDO. Rendus statiques, sans animation.</small></footer><script>const DATA=__DATA__,REF=__REF__,c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let entry,images={},visible={},schema=false,reference=false;function image(src){let im=new Image();im.src=src;return im}const ref=image(REF);function download(src,name){let a=document.createElement('a');a.href=src;a.download=name;a.click()}for(const [id,e]of Object.entries(DATA)){let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}select.value='salle_traversee';function setup(){entry=DATA[select.value];images={};visible={};const root=document.getElementById('layers');root.innerHTML='';for(const n of entry.layers){images[n]=image(entry.images[n]);visible[n]=!entry.optional.includes(n);const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=visible[n];ch.onchange=()=>visible[n]=ch.checked;a.href=entry.images[n];a.download=entry.id+'_'+n+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(n.replace(/^\\d+_/,'').replaceAll('_',' ')),a);root.append(l)}images.schema=image(entry.schema);document.getElementById('status').textContent=entry.title+' · Accès : '+entry.ports.map(p=>p.direction).join(' / ')+' · largeur de raccord 64px'}select.onchange=setup;document.getElementById('plan').onclick=e=>{schema=!schema;reference=false;e.target.textContent=schema?'Voir rendu':'Voir schéma des accès'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Revenir à la variante':'Voir référence canonique'};document.getElementById('export').onclick=()=>download(c.toDataURL(),reference?'reference_temple.png':entry.id+(schema?'_schema':'')+'.png');function draw(im){if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}function render(){const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){c.width=w;c.height=h}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else for(const n of entry.layers)if(visible[n])draw(images[n]);requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
h=h.replace('__DATA__',json.dumps(data)).replace('__REF__',json.dumps(ref_uri)).replace('__PLANCHE__',planche_uri)
(R/'apercu_temple_reseau_ledian_v1.html').write_text(h,encoding='utf8')
print("gallery -> apercu_temple_reseau_ledian_v1.html")
